/**
 * Daily new-plugin pages: /new and /new/YYYY-MM-DD.
 * Generated by prepare-pages-deploy.mjs. Not a /plugins/{slug} batch.
 *
 * Eligibility (one place, extend the sets below):
 * - manifest not_validated, or no install command
 * - HOLD_IDS (failed listability / explicit holds)
 * - clearly-MCP: EXPLICIT_MCP_IDS, or an "mcp" token in the name or id.
 *   Topic "mcp" alone does not exclude a normal dsh plugin.
 * - name collision with a live PLUGIN_SLUGS landing: the name or last id
 *   segment equals that slug (unless this row is the landing's own catalog
 *   id), or starts with "{slug}-", or ends with "-{slug}".
 *
 * Score is stars*2 + forks*0.2. Ties break by name, then id.
 * Do not print stars, forks, or the score.
 */
import { existsSync } from "node:fs";
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { PLUGIN_SLUGS } from "../functions/_middleware.js";
import { NEW_PLUGIN_COPY, NEW_PLUGIN_ROW_SEPARATOR } from "./new-plugins-copy.mjs";

export const SITE = "https://dsplugin.app";
export const HUB_PATH = "/new";
export const STYLES_VERSION = "20261111new";

/** Add catalog ids here. Topic "mcp" is not enough. */
export const EXPLICIT_MCP_IDS = new Set([
  "AcuteSZW/dsh-rea-pro",
  "wgl2zj/dsh-websearch-zai-codingplan",
]);

/** Failed-listability / HOLD rows. Empty until a list exists in the repo. */
export const HOLD_IDS = new Set();

export function isIsoDate(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return false;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
}

export function identityKey(raw) {
  if (raw == null) return "";
  let s = String(raw).trim().toLowerCase();
  if (!s) return "";
  if (s.startsWith("@")) s = s.slice(1);
  const parts = s.split(/[/#?]/).filter(Boolean);
  if (!parts.length) return "";
  let seg = parts[parts.length - 1];
  if (seg.startsWith("@")) seg = seg.slice(1);
  return seg;
}

export function newPluginScore(plugin) {
  const stars = Number(plugin && plugin.stars);
  const forks = Number(plugin && plugin.forks);
  return (Number.isFinite(stars) ? stars : 0) * 2 + (Number.isFinite(forks) ? forks : 0) * 0.2;
}

function hasInstall(plugin) {
  return typeof plugin.install === "string" && plugin.install.trim() !== "";
}

function hasMcpToken(plugin) {
  const blobs = [plugin && plugin.name, plugin && plugin.id];
  return blobs.some((raw) => /(^|[^a-z0-9])mcp([^a-z0-9]|$)/i.test(String(raw || "")));
}

function looksLikeLiveSlug(key, slug) {
  if (!key || !slug) return "";
  if (key === slug) return "equals";
  if (key.startsWith(`${slug}-`)) return "prefix";
  if (key.endsWith(`-${slug}`)) return "suffix";
  return "";
}

function nameCollision(plugin, ctx) {
  const keys = [];
  const nameKey = identityKey(plugin.name);
  const idKey = identityKey(plugin.id);
  if (nameKey) keys.push(nameKey);
  if (idKey && idKey !== nameKey) keys.push(idKey);
  for (const slug of ctx.slugs) {
    const owner = ctx.owners.get(slug) || "";
    for (const key of keys) {
      const kind = looksLikeLiveSlug(key, slug);
      if (!kind) continue;
      if (kind === "equals" && owner && plugin.id === owner) continue;
      return true;
    }
  }
  return false;
}

export function exclusionReason(plugin, ctx) {
  if (!plugin || typeof plugin !== "object" || !plugin.id) return "no_id";
  if (HOLD_IDS.has(plugin.id)) return "hold";
  if (EXPLICIT_MCP_IDS.has(plugin.id) || hasMcpToken(plugin)) return "mcp";
  const manifest = plugin.verification && plugin.verification.manifest;
  if (manifest === "not_validated") return "not_validated";
  if (!hasInstall(plugin)) return "missing_install";
  if (nameCollision(plugin, ctx)) return "collision";
  return null;
}

export function landingHref(plugin, ctx) {
  if (plugin && plugin.id && ctx && ctx.owners && ctx.slugs) {
    for (const [slug, owner] of ctx.owners) {
      if (owner && owner === plugin.id && ctx.slugs.has(slug)) return `/plugins/${slug}`;
    }
  }
  const id = plugin && plugin.id ? String(plugin.id) : "";
  return `/plugin-detail?plugin=${encodeURIComponent(id)}`;
}

export function oneSentence(plugin) {
  let raw = pickDescription(plugin).replace(/\s+/g, " ").trim();
  if (!raw) return "";
  const parts = raw.split(/\s\/\s/).map((part) => part.trim()).filter(Boolean);
  if (parts.length >= 2 && parts[0].length >= 24 && parts[1].length >= 12) raw = parts[0];
  for (let i = 0; i < raw.length; i++) {
    const ch = raw[i];
    if (ch === "。" || ch === "！" || ch === "？" || ch === "!" || ch === "?") {
      return raw.slice(0, i + 1).trim();
    }
    if (ch === "." || ch === "…") {
      if (ch === "…") return raw.slice(0, i + 1).trim();
      const prev = raw[i - 1] || "";
      const next = raw[i + 1] || "";
      if (/\d/.test(prev) && /\d/.test(next)) continue;
      if (next && /[A-Za-z0-9]/.test(next)) continue;
      return raw.slice(0, i + 1).trim();
    }
  }
  return raw;
}

function pickDescription(plugin) {
  const d = plugin && plugin.description;
  if (d == null) return "";
  if (typeof d === "string") return d;
  if (typeof d === "object") {
    if (typeof d.zh === "string" && d.zh.trim()) return d.zh;
    if (typeof d.en === "string" && d.en.trim()) return d.en;
    for (const value of Object.values(d)) {
      if (typeof value === "string" && value.trim()) return value;
    }
  }
  return "";
}

function displayName(plugin) {
  const name = typeof plugin.name === "string" ? plugin.name.trim() : "";
  return name || identityKey(plugin.id) || String(plugin.id);
}

function toRow(plugin, ctx) {
  return {
    id: String(plugin.id),
    name: displayName(plugin),
    sentence: oneSentence(plugin),
    href: landingHref(plugin, ctx),
    score: newPluginScore(plugin),
  };
}

function compareRows(a, b) {
  const diff = b.score - a.score;
  if (diff > 1e-9) return 1;
  if (diff < -1e-9) return -1;
  const byName = String(a.name).localeCompare(String(b.name), "zh-CN");
  if (byName) return byName;
  return String(a.id).localeCompare(String(b.id), "en");
}

export function buildNewPluginContext(plugins, slugs, canonicalBySlug = new Map()) {
  const owners = new Map();
  const list = Array.isArray(plugins) ? plugins : [];
  for (const slug of slugs) {
    const canon = canonicalBySlug.get(slug) || "";
    if (canon) {
      owners.set(slug, canon);
      continue;
    }
    const ids = new Set();
    for (const plugin of list) {
      if (!plugin || !plugin.id) continue;
      if (identityKey(plugin.id) === slug || identityKey(plugin.name) === slug) ids.add(plugin.id);
    }
    owners.set(slug, ids.size === 1 ? [...ids][0] : "");
  }
  return { slugs, owners };
}

export function groupEligibleNewPlugins(plugins, ctx) {
  const byDate = new Map();
  for (const plugin of plugins || []) {
    const date = plugin && plugin.addedAt;
    if (typeof date !== "string" || !isIsoDate(date)) continue;
    if (exclusionReason(plugin, ctx)) continue;
    let rows = byDate.get(date);
    if (!rows) {
      rows = [];
      byDate.set(date, rows);
    }
    rows.push(toRow(plugin, ctx));
  }
  for (const rows of byDate.values()) rows.sort(compareRows);
  const dates = [...byDate.keys()].sort();
  return {
    latest: dates.length ? dates[dates.length - 1] : null,
    dates,
    byDate,
  };
}

function esc(value) {
  return String(value).replace(/[&<>"']/g, (ch) => {
    if (ch === "&") return "&amp;";
    if (ch === "<") return "&lt;";
    if (ch === ">") return "&gt;";
    if (ch === '"') return "&quot;";
    return "&#39;";
  });
}

function rowHtml(row) {
  const sentence = row.sentence ? `${NEW_PLUGIN_ROW_SEPARATOR}${esc(row.sentence)}` : "";
  return `<li><a href="${esc(row.href)}">${esc(row.name)}</a>${sentence}</li>`;
}

