function decodeAttr(value) {
  return String(value)
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");
}

async function readCanonicalIds(pluginsDir, slugs) {
  const map = new Map();
  let entries = [];
  try {
    entries = await readdir(pluginsDir);
  } catch {
    return map;
  }
  for (const file of entries) {
    if (!file.endsWith(".html")) continue;
    const slug = file.slice(0, -".html".length);
    if (!slugs.has(slug)) continue;
    const html = await readFile(join(pluginsDir, file), "utf8");
    const m = html.match(/data-plugin-id="([^"]*)"/);
    map.set(slug, m ? decodeAttr(m[1]) : "");
  }
  return map;
}

export async function loadNewPluginContext({ plugins, pluginsDir, slugs = PLUGIN_SLUGS } = {}) {
  const canon = pluginsDir ? await readCanonicalIds(pluginsDir, slugs) : new Map();
  return buildNewPluginContext(plugins, slugs, canon);
}

export async function writeNewPluginPages({
  outDir,
  plugins,
  pluginsDir,
  slugs = PLUGIN_SLUGS,
  canonicalBySlug,
} = {}) {
  if (!outDir) throw new Error("outDir is required");
  const dest = resolve(outDir);
  if (existsSync(join(dest, "functions", "_middleware.js"))) {
    throw new Error("refusing to write /new pages into the repo root");
  }
  const canon = canonicalBySlug || (pluginsDir ? await readCanonicalIds(pluginsDir, slugs) : new Map());
  const ctx = buildNewPluginContext(plugins, slugs, canon);
  const grouped = groupEligibleNewPlugins(plugins, ctx);
  const dir = join(dest, "new");
  await rm(dir, { recursive: true, force: true });
  const counts = {};
  for (const date of grouped.dates) counts[date] = grouped.byDate.get(date).length;
  if (!grouped.latest) {
    return { latest: null, dates: [], counts, files: [] };
  }
  await mkdir(dir, { recursive: true });
  const files = [];
  for (const date of grouped.dates) {
    const html = renderNewPluginPage({ date, rows: grouped.byDate.get(date), kind: "date" });
    const file = join(dir, `${date}.html`);
    await writeFile(file, html);
    files.push(file);
  }
  const hub = renderNewPluginPage({
    date: grouped.latest,
    rows: grouped.byDate.get(grouped.latest),
    kind: "hub",
  });
  const hubFile = join(dir, "index.html");
  await writeFile(hubFile, hub);
  files.push(hubFile);
  return { latest: grouped.latest, dates: grouped.dates, counts, files };
}
